// v4.4.0: course-page CSP setting.
$string['settings:csp_course_pages_mode'] = 'Content-Security-Policy voor cursuspagina\'s';
$string['settings:csp_course_pages_mode_desc'] = 'Optionele CSP-header op cursuspagina\'s waar de widget van de AI-cursusassistent actief is. <strong>Uit</strong>: geen header (standaard). <strong>Alleen rapporteren</strong>: stuur <code>Content-Security-Policy-Report-Only</code> — browsers loggen overtredingen maar blokkeren niets. Handig voor een observatieperiode van een week. <strong>Afdwingen</strong>: stuur <code>Content-Security-Policy</code> — browsers blokkeren iframe-bronnen buiten de allowlist, fetches en andere riskante ladingen. Helpt de impact te beperken van willekeurige scripts die in de siteconfiguratie Additional HTML zijn geplakt (het IBL AI / Raison-incident van 2026-04-29). Heeft geen invloed op de eindpunten van [[tutorshort]], die altijd een strengere CSP sturen.';
$string['settings:csp_mode_off'] = 'Uit (geen header op cursuspagina\'s)';
$string['settings:csp_mode_report_only'] = 'Alleen rapporteren (overtredingen loggen, niet blokkeren)';
$string['settings:csp_mode_enforce'] = 'Afdwingen (ladingen buiten de allowlist blokkeren)';
// v4.5.0: site-wide pedagogy defaults.
$string['settings:pedagogy_defaults_heading'] = 'Pedagogische standaardwaarden';
$string['settings:pedagogy_defaults_heading_desc'] = 'Sitebrede standaardstatus voor elke pedagogische functie. Zet hier een functie aan en elke cursus neemt die over, tenzij die cursus een expliciete overschrijving heeft op zijn pagina met [[tutorshort]]-cursusinstellingen (geforceerd aan / geforceerd uit). Bij de upgrade naar v4.5.0 wordt elke overschrijving "geforceerd uit" per cursus die op de verouderde standaardwaarde <code>0</code> stond gewist, zodat de nieuwe globale standaardwaarden schoon van kracht worden. Standaard uit — upgrades vanaf v4.4.x veranderen niets totdat een beheerder een functie aanzet.';
$string['pedagogy:mastery'] = 'Beheersingsregistratie standaard aan';
$string['pedagogy:mastery_desc'] = 'Wanneer aan, neemt elke cursus beheersingsregistratie over, tenzij de cursus een eigen overschrijving heeft. Beheersing vereist samengestelde leerdoelen — cursussen zonder leerdoelen vallen netjes terug, zonder foutmelding.';
$string['pedagogy:socratic_mode'] = 'Socratische modus standaard aan';
