// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = 'Leveranciers- en kostengegevens';
$string['settings:vendor_data_heading_desc'] = 'Instellingen voor de optionele beheerderspagina Leveranciers-DPA en voor de overschrijvingseditors waarmee beheerders de meegeleverde leverancierstabel en de LLM-tariefkaart actueel houden zonder de code aan te passen. Beide overschrijvingseditors werken met JSON; een lege waarde valt terug op de vaste standaardwaarden die met de plugin zijn meegeleverd.';
$string['settings:vendor_dpa_admin_page_enabled'] = 'Beheerderspagina Leveranciers-DPA tonen';
$string['settings:vendor_dpa_admin_page_enabled_desc'] = 'Wanneer dit aanstaat, verschijnt "DPA-status leverancier" onder Siteadministratie → Plug-ins → Lokale plug-ins → AI-cursusassistent. De pagina toont de leverancierstabel samengevoegd met de onderstaande overschrijving. Standaard uit — de meeste beheerders hebben dit scherm niet nodig.';
$string['settings:vendor_dpa_overrides'] = 'Overschrijvingen leveranciers-DPA (JSON)';
$string['settings:vendor_dpa_overrides_desc'] = 'JSON object keyed by vendor id. Each value is an object whose fields override the hardcoded vendor row. Fields you do not specify fall through to the default. A new vendor key in the override is added to the table; edits apply per field. Malformed JSON is ignored at runtime — fix the parse error here when the saved value does not appear in the Vendor DPA page.';
$string['settings:rate_card_overrides'] = 'Overschrijvingen LLM-tariefkaart (JSON)';
$string['settings:rate_card_overrides_desc'] = 'JSON-object met de modelnaamprefix als sleutel. Elke waarde is <code>{"input": float, "output": float}</code> in USD per 1.000.000 tokens. Vervangt de meegeleverde tariefkaartregel voor die prefix. Voorbeeld: <pre>{ "gpt-4o-mini": { "input": 0.15, "output": 0.60 }, "claude-sonnet-4.6": { "input": 3.00, "output": 15.00 } }</pre> Alleen-lezen vanaf v7.4.0: dit veld wordt nog steeds samengevoegd (boven de meegeleverde basis, onder het modelregister) zodat een bestaande override blijft werken, maar er schrijft niets meer naartoe en nieuwe prijzen horen in het modelregister, dat vastlegt wie elke prijs heeft ingesteld en wanneer. De wekelijkse verversing overschreef vroeger dit hele veld, waardoor elke met de hand ingevoerde prijs bij de volgende run verloren ging.';

// v4.7.0: rate-card auto-refresh.
$string['settings:rate_card_auto_refresh'] = 'Automatisch vernieuwen vanaf upstream';
$string['settings:rate_card_auto_refresh_desc'] = 'Wanneer aan, haalt een wekelijkse geplande taak (maandag 02:30 servertijd) de upstream prijs-JSON hieronder op, zet die om naar het tariefkaartschema van [[tutorshort]] en schrijft elke prijs rij voor rij in het modelregister. Standaard aan — zet uit om de tariefkaart vast te pinnen op wat het laatst is opgehaald of met de hand is ingevoerd. Een prijs die een beheerder heeft ingevoerd, wordt door deze verversing nooit overschreven, en een mislukte run schrijft helemaal niets; de status van de laatste verversing verschijnt onder de knop Nu verversen.';
$string['settings:rate_card_upstream_url'] = 'Upstream-URL met prijzen';
