$string['settings:talking_avatar_did_api_key_desc'] = 'Base64-gecodeerde tekenreeks <code>email:api-key</code> uit <a href="https://studio.d-id.com/account-settings" target="_blank" rel="noopener">D-ID Studio → Account → API keys</a>. Wordt verzonden als <code>Authorization: Basic …</code>.';
$string['settings:talking_avatar_did_persona_id'] = 'URL van de D-ID-bronafbeelding';
$string['settings:talking_avatar_did_persona_id_desc'] = 'Publieke HTTPS-URL van de stilstaande afbeelding die D-ID animeert (of een Studio-presenter-URL zoals <code>https://create-images-results.d-id.com/…</code>). Vereist voor elke stream.';
