$string['settings:avatar_rate_card_overrides'] = 'Overschrijvingen avatartariefkaart (JSON)';
$string['settings:avatar_rate_card_overrides_desc'] = 'JSON-object met de avatarprovider als sleutel en één USD-tarief per minuut. Vervangt het meegeleverde tarief voor die provider. Voorbeeld: <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> Leeg = gebruik de meegeleverde standaardwaarden van v4.10.0: D-ID $0,30/min, HeyGen $0,50/min, Tavus $0,30/min, Synthesia $0,40/min. Stel dit in op uw contractuele tarief zodat het analysedashboard de werkelijke kosten van de instelling weergeeft.';
$string['settings:talking_avatar_did_webhook_secret'] = 'D-ID webhook-ondertekeningsgeheim';
$string['settings:talking_avatar_did_webhook_secret_desc'] = 'Optioneel. Wanneer dit is ingesteld, kan D-ID sessie-eindgebeurtenissen POSTen naar <code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code>, ondertekend met dit geheim als <code>X-DID-Signature</code> (hex HMAC-SHA256). Webhookrijen hebben voorrang op de heartbeat van de frontend. Leeg = handler uit, de heartbeat en de uurlijkse opruimtaak handelen het einde van een sessie volledig zelf af.';
$string['settings:talking_avatar_heygen_webhook_secret'] = 'HeyGen webhook-ondertekeningsgeheim';
$string['settings:talking_avatar_heygen_webhook_secret_desc'] = 'Optioneel. Wanneer dit is ingesteld, kan HeyGen sessie-eindgebeurtenissen POSTen, ondertekend met dit geheim als <code>X-HeyGen-Signature</code> (hex HMAC-SHA256). Leeg = handler uit.';
$string['settings:talking_avatar_tavus_webhook_secret'] = 'Tavus webhook-ondertekeningsgeheim';
$string['settings:talking_avatar_tavus_webhook_secret_desc'] = 'Optioneel. Wanneer dit is ingesteld, kan Tavus eindgebeurtenissen van gesprekken POSTen, ondertekend met dit geheim als <code>X-Tavus-Signature</code> (hex HMAC-SHA256). Leeg = handler uit.';
$string['settings:talking_avatar_synthesia_webhook_secret'] = 'Synthesia webhook-ondertekeningsgeheim';
$string['settings:talking_avatar_synthesia_webhook_secret_desc'] = 'Optioneel. Wanneer dit is ingesteld, kan Synthesia eindgebeurtenissen van agentsessies POSTen, ondertekend met dit geheim als <code>X-Synthesia-Signature</code> (hex HMAC-SHA256). Leeg = handler uit.';
