$string['task:sweep_avatar_sessions'] = 'Verouderde sessies met de pratende avatar sluiten';
$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Uitgebreide prompt voor Socratische modus';
$string['settings:socratic_verbose_desc'] = 'Wanneer dit aanstaat, krijgen cursussen in Socratische modus de volledige do\'s-en-don\'ts-richtlijn van ~600 tokens die oorspronkelijk in v3.9.30 is toegevoegd. Wanneer het uitstaat (standaard), krijgen ze een richtlijn van één regel die moderne gehoste modellen betrouwbaar opvolgen en die ~600 tokens per beurt bespaart. Zet dit aan als een cursus draait op een zwakker zelfgehost model dat de expliciete steigers nodig heeft.';
$string['settings:prompt_budget_chars'] = 'Tekenbudget voor de systeemprompt';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Limiet inhoud huidige pagina (tekens)';
$string['settings:current_page_content_maxchars_desc'] = 'Maximaal aantal tekens van de tekst van de huidige pagina dat als sectie "Current Page Content" in de systeemprompt wordt ingevoegd wanneer RAG is uitgeschakeld. De standaardwaarde 8,000 onderbouwt paginaspecifieke vragen goed en laat tegelijk budget over voor structuur en instructies. (Met RAG ingeschakeld wordt de pagina in plaats daarvan onderbouwd door haar eigen meest relevante fragmenten, met voorkeur voor de huidige pagina, dus deze limiet is niet van toepassing.) Een zeer lange pagina wordt vanaf het begin afgekapt tot dit aantal tekens, dus het einde van een extreem lange pagina wordt mogelijk niet geciteerd; het inschakelen van RAG voorkomt dat. Kostenbewuste sites kunnen deze lager beperken (bijv. 3,000-4,000). Beperkt tot het bereik 500-8,000. Onafhankelijk van <code>prompt_budget_chars</code>: dit beperkt alleen de paginasectie; het budget beperkt de hele prompt.';
$string['settings:prompt_verbosity'] = 'Uitgebreidheid van de prompt';
$string['settings:prompt_verbosity_desc'] = 'Standaarduitgebreidheid voor instructieblokken (Socratische modus, externe bronnen). Beknopt (standaard) is wat moderne gehoste modellen betrouwbaar opvolgen; standaard voegt expliciete steigers toe voor modellen uit het middensegment; uitgebreid behoudt de zware richtlijnen uit het v3.9.30-tijdperk voor zwakkere zelfgehoste modellen. Overschrijving per cursus is beschikbaar via <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'Beknopt (aanbevolen voor gehoste modellen)';
$string['settings:prompt_verbosity_standard'] = 'Standaard';
$string['settings:prompt_verbosity_verbose'] = 'Uitgebreid (voor zwakkere zelfgehoste modellen)';
$string['settings:prompt_metrics_enabled'] = 'Promptmetingen per sectie vastleggen';
$string['settings:prompt_metrics_enabled_desc'] = 'Wanneer dit aanstaat (standaard), schrijft elke chatbeurt één JSON-regel per samengestelde prompt naar <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code>, met het aantal tekens per categorie. De laatste 7 dagen worden bewaard. De beheerderspagina met metingen aggregeert deze voor de budgetaanbeveling. Er worden geen persoonsgegevens (PII) vastgelegd — alleen sectiegroottes. Zet dit uit als uw instelling liever helemaal geen metingenbestand heeft.';
$string['settings:prompt_budget_auto_tune'] = 'Dagelijkse automatische afstemming van het systeempromptbudget (verouderd)';
$string['settings:prompt_budget_auto_tune_desc'] = 'Verouderd. Doet niets tenzij de budgetmodus hierboven op <strong>Vast</strong> staat. Een dagelijkse taak leidde het tekenbudget af door op afkapping te letten en de grootste prompt na te jagen die zij had gezien. Het budget afleiden uit het contextvenster van het model doet dat beter: het kan niet oscilleren en heeft geen aanloopgegevens nodig. Beide botsten ook, want de taak schrijft het tekenbudget en elke waarde behalve de standaard schakelt het afgeleide budget uit. Laat dit uit staan; het wordt in een toekomstige versie verwijderd. De aanbeveling verschijnt nog steeds op de pagina <a href="/local/ai_course_assistant/prompt_metrics.php">Promptmetingen</a>.';
