// v5.3.0: Empathetic communications + carryover memory (English fallback).
$string['task:milestone_check'] = 'Dagelijkse e-mails met mijlpaalreflectie verzenden (v5.3.0)';
$string['task:struggle_signal_review'] = 'Signalen van leermoeilijkheden beoordelen en opnemen in het privégeheugen van de cursist (v5.3.0)';
$string['empathy:title'] = 'Empathische communicatie en doorlopend geheugen (v5.3.0)';
$string['empathy:desc'] = 'Drie op elkaar afgestemde functies die [[tutorshort]] meer laten aanvoelen als een coach die luistert. Doelen leggen vast waarom de student hier is. Het doorlopende geheugen onthoudt wat eerder moeilijk was, zodat [[tutorshort]] een andere invalshoek kan bieden. Mijlpalen vieren reeksen actieve dagen en afgeronde cursussen per e-mail. Elke functie heeft een eigen noodschakelaar en vereist toestemming van de student. Vastloopsignalen verlaten de chat nooit — er wordt nooit een e-mail verstuurd over een moeilijke sessie.';
$string['empathy:outreach_master_enabled'] = 'Hoofdnoodschakelaar voor proactieve e-mails';
$string['empathy:outreach_master_enabled_desc'] = 'Standaard uit bij een verse installatie. Wanneer dit uitstaat, wordt er NOOIT een empathische e-mail van welke aard dan ook verstuurd, ongeacht de onderstaande schakelaars per functie. Zet dit aan zodra u de standaardwaarden per functie en de toestemmingsstroom per student hebt doorgenomen.';
$string['empathy:goals_enabled'] = 'Gesprekken over loopbaandoelen inschakelen';
$string['empathy:goals_enabled_desc'] = 'Laat studenten uit eigen beweging twee korte antwoorden geven (waarom ze hier zijn, wat ze willen worden) die de personalisatie voeden. Alleen in de chat; geen e-mails. Veilig om aan te laten staan.';
$string['empathy:milestones_enabled'] = 'E-mails met mijlpaalreflectie inschakelen';
$string['empathy:milestones_enabled_desc'] = 'Stuurt een korte, hartelijke e-mail wanneer een student 7 dagen op rij of 30 dagen op rij actief is geweest of de cursus heeft afgerond. Vereist de hoofdschakelaar hierboven plus toestemming per student. Harde limiet van één e-mail per student per 7 dagen over alle kanalen samen.';
$string['empathy:memory_enabled'] = 'Doorlopend personalisatiegeheugen inschakelen';
$string['empathy:memory_enabled_desc'] = 'Laat [[tutorshort]] kleine privénotities over wat een student moeilijk vond meenemen naar volgende sessies, zodat het volgende antwoord een andere invalshoek kan bieden. Begrensd (maximaal 5 notities per student per cursus, bewaartermijn van 90 dagen). Bewerkbaar door de student. Nooit zichtbaar voor docenten.';
$string['empathy:struggle_enabled'] = 'Vastloopdetectie inschakelen';
$string['empathy:struggle_enabled_desc'] = 'Standaard uit. Laat [[tutorshort]] aanhoudende frustratie over meerdere beurten herkennen en stilletjes een knelpuntnotitie vastleggen in het doorlopende geheugen hierboven. De uitvoer blijft in de chat; er wordt nooit een e-mail verstuurd over een sessie met frustratie. Signaalgegevens worden na 7 dagen automatisch gewist.';
$string['empathy:outreach_dryrun'] = 'Proefdraaien (loggen zonder te verzenden)';
$string['empathy:outreach_dryrun_desc'] = 'Wanneer dit aanstaat, schrijft de geplande mijlpaaltaak auditregels alsof er e-mails zijn verzonden, maar wordt er niemand daadwerkelijk gemaild. Gebruik dit op een verse installatie om de afkoelperiode en de toestemmingslogica te controleren voordat u live gaat.';
