$string['coursesettings:apibaseurl_rejected'] = 'De basis-URL van de API is niet opgeslagen: het moet een openbaar HTTPS-eindpunt zijn dat de SSRF-veiligheidscontrole doorstaat.';
$string['settings:escalation_intent_patterns'] = 'Patronen voor escalatie-intentie';
$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. Eén reguliere expressie per regel; regels die met # beginnen worden genegeerd. Een supportticket wordt alleen geopend wanneer het eigen bericht van de cursist overeenkomt met een van deze patronen, zodat cursusinhoud geen escalatie namens de cursist kan veroorzaken. Laat leeg om de ingebouwde standaardwaarden te gebruiken; die dekken Engels plus enkele gangbare formuleringen in het Spaans, Frans, Duits en Portugees. Sites waarvan de cursisten in een andere taal schrijven, kunnen hier patronen toevoegen: een bericht zonder overeenkomst betekent dat er geen ticket wordt geopend.';
$string['settings:zendesk_require_consent'] = 'Toestemming vereisen vóór escalatie naar ondersteuning';
$string['settings:zendesk_require_consent_desc'] = 'Wanneer ingeschakeld (aanbevolen), escaleert [[tutorshort]] een gesprek pas naar de Zendesk-ondersteuningsdesk nadat de lerende de toestemmingsmelding bij het eerste gebruik heeft geaccepteerd, die meldt dat het vragen om menselijke hulp het gesprek (inclusief naam en e-mail) deelt met ondersteuning. Schakel dit alleen uit als u die toestemming op een andere manier verkrijgt; met dit uitgeschakeld worden escalaties onmiddellijk verzonden. Heeft geen effect tenzij Zendesk-escalatie is ingeschakeld.';
$string['chat:escalation_needs_consent'] = 'Het lijkt erop dat hiervoor een lid van ons ondersteuningsteam nodig is. Om dit aan hen door te geven zou ik dit gesprek, inclusief uw naam en e-mailadres, met de ondersteuningsdesk moeten delen. U bent daar nog niet mee akkoord gegaan, dus ik heb niets verzonden. Als u menselijke hulp wenst, accepteer dan de melding over gegevensdeling voor deze assistent en vraag het opnieuw, of neem rechtstreeks contact op met ondersteuning.';
$string['privacy:metadata:email_optout'] = 'Voorkeuren voor e-mailafmelding per ontvanger (van welke e-mailtypen een ontvanger zich heeft afgemeld).';
$string['privacy:metadata:email_optout:email'] = 'Het e-mailadres van de ontvanger waarop de afmelding van toepassing is.';
$string['privacy:metadata:email_optout:optout_type'] = 'Het e-mailtype waarvoor de ontvanger zich heeft afgemeld.';
$string['privacy:metadata:email_optout:userid'] = 'De Moodle-gebruiker aan wie de afmelding toebehoort, indien bekend.';
$string['chat:consent_scroll_hint'] = 'Scrol naar beneden om de volledige kennisgeving te lezen voordat u doorgaat.';
$string['settings:rag_min_similarity'] = 'Minimale relevantie (cosinus)';
$string['settings:rag_min_similarity_desc'] = 'Verwijder opgehaalde fragmenten waarvan de cosinusgelijkenis met de vraag onder deze waarde ligt, zodat een vraag buiten het onderwerp of met weinig inhoud minder (of nul) passages invoegt in plaats van altijd op te vullen tot Top-K met zwakke overeenkomsten. Bereik 0 tot 1; 0 schakelt de poort uit. De juiste waarde hangt af van het embeddingmodel: 0.25 past bij text-embedding-3-small. Verhoog deze om strenger te zijn (minder, meer ter zake doende context), verlaag deze om toleranter te zijn.';
$string['settings:rag_currentpage_boost'] = 'Boost huidige pagina';
$string['settings:rag_currentpage_boost_desc'] = 'Een kleine bonus die wordt toegevoegd aan de relevantiescore van fragmenten van de pagina die de cursist op dit moment bekijkt, zodat vragen als "leg dit uit" de voorkeur geven aan de zichtbare pagina wanneer de scores dicht bij elkaar liggen. Alleen ordening: het dwingt een irrelevant paginafragment niet voorbij de poort voor minimale relevantie. Stel in op 0 om uit te schakelen.';
$string['settings:history_mode'] = 'Selectiemodus voor geschiedenis';
$string['settings:history_mode_desc'] = 'Hoe eerdere gespreksbeurten worden gekozen voordat ze naar het model worden verzonden. <strong>Semantisch</strong> behoudt alleen de recente beurten die relevant zijn voor de huidige vraag (en altijd de meest recente uitwisseling), zodat een verouderde, niet ter zake doende eerdere beurt de kosten niet opdrijft of het antwoord niet van koers brengt; het doet één extra embedding-aanroep per bericht. <strong>Recentheid</strong> behoudt de laatste "Max Conversation History"-paren ongeacht relevantie (het langbestaande gedrag, geen extra aanroep). Als embedding niet beschikbaar is, valt de semantische modus automatisch terug op recentheid.';
$string['settings:history_mode_semantic'] = 'Semantisch (relevante recente beurten)';
$string['settings:history_mode_recency'] = 'Recentheid (laatste N paren)';
$string['settings:history_semantic_minscore'] = 'Ondergrens relevantie geschiedenis (cosinus)';
$string['settings:history_semantic_minscore_desc'] = 'In de semantische geschiedenismodus wordt een eerdere beurt alleen behouden als de gelijkenis met de huidige vraag minstens deze waarde is (de meest recente uitwisseling wordt altijd behouden). Bereik 0 tot 1; modelafhankelijk. Verhoog om strenger te zijn (minder geschiedenis), verlaag om meer te behouden.';
$string['settings:history_candidates'] = 'Kandidatenvenster geschiedenis';
$string['settings:history_candidates_desc'] = 'In de semantische geschiedenismodus krijgen alleen de meest recente zoveel paren een relevantiescore (een kostengrens). Paren die ouder zijn dan dit venster worden niet verzonden. Houd deze waarde op of boven "Max Conversation History".';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — aanbevolen; +4 MTEB t.o.v. OpenAI 3-small, 4× context, meertalig)';
$string['settings:rerank_heading'] = 'RAG: Tweeledige opvraging (herrangschikking)';
$string['settings:rerank_heading_desc'] = 'Optionele tweede opvragingsfase: cosinus-gelijkenis selecteert de beste N kandidaatfragmenten (standaard 50), waarna een cross-encoder herrangschikker elk (vraag, fragment)-paar beoordeelt en de beste K fragmenten in de prompt worden opgenomen. Standaard uitgeschakeld; valt terug op enkelvoudige cosinus als de herrangschikker niet is geconfigureerd of mislukt.';
$string['settings:rerank_enabled'] = 'Tweeledige opvraging (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'Wanneer ingeschakeld wordt RAG-opvraging tweeledig: cosinus-gelijkenis geeft de beste N kandidaten terug (standaard 50), waarna de Voyage rerank-2.5 cross-encoder elk beoordeelt en de beste K in de prompt worden opgenomen. Gepubliceerde verbeteringen: +15 Recall@10 enterprise, +39% NDCG BEIR. ~€0,05/MTok-facturering. Vereist <code>rerank_apikey</code> hieronder; valt soepel terug op enkelvoudige cosinus als herrangschikken mislukt of niet is geconfigureerd.';
$string['settings:rerank_apikey'] = 'Rerank API-sleutel';
$string['settings:rerank_apikey_desc'] = 'Voyage AI API-sleutel voor rerank-2.5. Leeg laten om de bovenstaande Embedding API-sleutel opnieuw te gebruiken (typische Voyage-implementaties delen één sleutel voor embed + rerank).';
$string['settings:rerank_model'] = 'Rerank-model';
$string['settings:rerank_model_desc'] = 'Standaard <code>rerank-2.5</code>. Nieuwere Voyage rerank-modellen kunnen hier worden opgegeven.';
$string['settings:rerank_apibaseurl'] = 'Rerank API basis-URL';
$string['settings:rerank_apibaseurl_desc'] = 'Overschrijf de Voyage rerank basis-URL. Leeg laten om de bovenstaande Embedding API basis-URL of de Voyage-standaard te gebruiken (<code>https://api.voyageai.com/v1</code>).';
$string['settings:rerank_candidates'] = 'Rerank kandidatenvenster';
$string['settings:rerank_candidates_desc'] = 'Hoeveel cosinus-top-N-kandidaten de herordeningsfase ingaan. Standaard 20. Gemeten over 1.008 zoekopdrachten: 20 evenaart 30 op recall (R@3 89,0 % tegen 89,3 %) voor een derde minder kosten, en 50 kost 2,5 keer zoveel zonder meetbare winst. Onder 10 verslechtert de recall. De kosten stijgen lineair met deze waarde.';
$string['settings:stt_selfhosted_heading'] = 'Zelfgehoste transcriptie (Whisper)';
$string['settings:stt_selfhosted_heading_desc'] = 'Voer spraak-naar-tekst uit op uw eigen hardware zonder kosten per minuut. Wijs [[tutorshort]] naar een OpenAI-compatibele transcriptieserver: <code>whisper-server</code> Docker, <code>speaches</code> (faster-whisper) of <code>whisper.cpp</code>-server. Wanneer hier een server-URL is ingesteld, wordt dit het standaard STT-pad; kies een betaalde aanbieder bij de bovenstaande instelling Actieve STT-aanbieder om dit te overschrijven. Als de server zich op een privénetwerk of gewoon http bevindt, voeg dan ook de host toe aan de SSRF-vertrouwde eindpunten-allowlist in het gedeelte Beveiliging.';
$string['settings:stt_selfhosted_url'] = 'Zelfgehoste STT-server URL';
$string['settings:stt_selfhosted_url_desc'] = 'Basis-URL van de OpenAI-compatibele transcriptieserver, bijvoorbeeld <code>http://10.0.0.5:8000</code>. [[tutorshort]] voegt automatisch <code>/v1/audio/transcriptions</code> toe; een volledig eindpuntpad wordt ook geaccepteerd. Leeg laten om zelfgehoste STT uit te schakelen.';
$string['settings:stt_selfhosted_model'] = 'Zelfgehoste STT-model';
$string['settings:stt_selfhosted_model_desc'] = 'Modelnaam die aan de server wordt doorgegeven, overeenkomend met het geladen Whisper-model — bijvoorbeeld <code>Systran/faster-whisper-small</code> voor speaches of <code>large-v3</code>. Leeg laten om <code>whisper-1</code> te verzenden, dat de meeste zelfgehoste servers accepteren of negeren.';
$string['settings:stt_selfhosted_apikey'] = 'Zelfgehoste STT API-sleutel';
$string['settings:stt_selfhosted_apikey_desc'] = 'Optioneel. De meeste zelfgehoste servers werken zonder sleutel achter een vertrouwd netwerk; stel dit alleen in als uw server een bearer-token vereist.';
$string['emergency:title'] = '[[tutorshort]] Noodcontroles';
$string['emergency:page_warning'] = 'Deze schakelaars worden onmiddellijk van kracht voor elke lerende op de site. Elke actie schrijft een auditregel. Gedetailleerde schakelaars laten de rest van [[tutorshort]] draaien; de hoofdschakelaar verwijdert de widget volledig.';
$string['emergency:back_to_settings'] = '[[tutorshort]] Instellingen';
$string['emergency:state_disabled'] = 'UITGESCHAKELD';
$string['emergency:state_active'] = 'Actief';
$string['emergency:confirm_label'] = 'Ik begrijp dat dit onmiddellijk van invloed is op elke lerende';
$string['emergency:confirm_required'] = 'Vink het bevestigingsvakje aan voordat u een subsysteem uitschakelt.';
$string['emergency:reason_placeholder'] = 'Reden (vastgelegd in het auditlogboek)';
$string['emergency:disable_button'] = 'Uitschakelen';
$string['emergency:restore_button'] = 'Herstellen';
$string['emergency:disabled_notice'] = 'Subsysteem "{$a->flag}" uitgeschakeld. Configuratie gewijzigd: {$a->touched}';
$string['emergency:restored_notice'] = 'Subsysteem "{$a->flag}" hersteld. Configuratie gewijzigd: {$a->touched}';
$string['emergency:cli_reference'] = 'Dezelfde bediening is beschikbaar via de wachtdienstshell:';
$string['emergency:flag_chat'] = 'Chat';
$string['emergency:flag_chat_desc'] = 'Stopt alle AI-aanroepen van [[tutorshort]] — chat, quizzen, flashcards en beoordeling — voor cursisten, beheerders en geplande taken. De widget blijft zichtbaar en cursisten zien een korte pauzemelding. De backend-zelftest en gezondheidscontrole blijven beschikbaar, zodat u de provider kunt controleren voordat u herstelt.';
$string['emergency:flag_voice'] = 'Spraak';
$string['emergency:flag_voice_desc'] = 'Verwijdert de actieve realtime spraak-aanbieder (opgeslagen voor exacte herstel). Tekstchat blijft werken.';
$string['emergency:flag_rag'] = 'RAG';
$string['emergency:flag_rag_desc'] = 'Schakelt opvraging en indexering uit. Chat gaat door zonder cursusinhoud als grondslag.';
$string['emergency:flag_outreach'] = 'Outreach';
$string['emergency:flag_outreach_desc'] = 'Stopt samenvattings-, mijlpaal- en herinneringsmails. Chat wordt niet beïnvloed.';
$string['emergency:flag_all'] = 'HOOFDSCHAKELAAR';
$string['emergency:flag_all_desc'] = 'Schakelt de hele plug-in uit: widget verdwijnt van elke pagina, geplande taken stoppen, spraak wordt verwijderd, RAG is uit, outreach is uit. De sterkste schakelaar — gebruik bij een beveiligingsincident of wanneer [[tutorshort]] onmiddellijk offline moet.';
$string['emergency:settings_link'] = 'Noodcontroles';
$string['emergency:settings_link_desc'] = 'Per-subsysteem kill-schakelaars (chat / spraak / RAG / outreach / hoofd) met auditregistratie — het webequivalent van <code>admin/cli/emergency_disable.php</code>. Open <a href="{$a}">[[tutorshort]] Noodcontroles</a>.';
$string['email_unsubscribe:done_title'] = 'Afgemeld';
$string['email_unsubscribe:done_body'] = 'Klaar — {$a->email} ontvangt voortaan geen e-mails van dit type meer van {$a->product}. Als u van gedachten verandert, vraag dan een {$a->product}-beheerder om het abonnement opnieuw in te schakelen, of stuur een nieuw opt-in verzoek via de pagina [[tutorshort]] Ontvangers beheer.';
$string['email_unsubscribe:invalid_title'] = 'Afmeldlink niet langer geldig';
$string['email_unsubscribe:invalid_body'] = 'Deze afmeldlink is verlopen of heeft een onjuist formaat. Zoek naar een recentere e-mail van ons, of neem contact op met een sitebeheerder om handmatig te worden verwijderd.';
$string['settings:prompt_proportions_heading'] = 'Promptsectieverhoudingen (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Verdeel het systeempromptbudget over vier emmers: veiligheid + identiteit, cursusstructuur, cursusinhoud en huidige pagina. Gewichten zijn percentages die optellen tot 100. Empirisch afgestemde standaarden (10 / 10 / 40 / 40) komen uit de v5.6.0-gewichtsafstemmingsbenchmark; het leeg laten van het tekstveld gebruikt die standaarden. De automatische versterking past de verdeling per beurt aan afhankelijk van of een specifieke pagina in scope is.';
$string['settings:prompt_section_weights'] = 'Basissectiegewichten (JSON)';
$string['settings:prompt_section_weights_desc'] = 'Optioneel JSON-object dat elke emmer aan een percentage koppelt. Leeg laten om de gebenchmarkte standaarden te gebruiken (10 / 10 / 40 / 40). Voorbeeld: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Gewichten moeten optellen tot 100 (±5%). <code>safety_identity</code> heeft een vloer van 10% zodat jailbreak-weerstand en uitvoerformaatmarkeringen altijd volledig worden opgenomen. <code>current_page + course_content</code> moet minimaal 40% zijn zodat het model voldoende materiaal heeft om op te baseren. Waarden buiten bereik vallen stilzwijgend terug op de gebenchmarkte standaarden; beheerders dienen te valideren door het prompt-debuglogboek na het opslaan te controleren.';
$string['settings:prompt_context_boost_mode'] = 'Contextversterkinsgmodus';
$string['settings:prompt_context_boost_mode_desc'] = 'Automatische aanpassing die gewicht verschuift naar de huidige pagina-sectie wanneer een specifieke pagina in scope is, en naar cursusinhoud wanneer geen pagina is geselecteerd. <strong>page_focus</strong> (standaard) verschuift ongeveer 15 gewichtspunten. <strong>aggressive</strong> verschuift 25 punten en is het beste wanneer lerende consequent paginaspecifieke vragen stellen. <strong>off</strong> schakelt de versterking uit; door de beheerder ingestelde basisgewichten gelden op elke beurt ongeacht de paginacontext.';
$string['settings:prompt_context_boost_off'] = 'Uit (basisgewichten op elke beurt gebruiken)';
$string['settings:prompt_context_boost_page_focus'] = 'Pagina-focus (standaard, ~15 punten verschuiving)';
$string['settings:prompt_context_boost_aggressive'] = 'Agressief (~25 punten verschuiving)';
$string['settings:prompt_section_weights_coach'] = 'Coach-modus overschrijving (JSON, optioneel)';
$string['settings:prompt_section_weights_coach_desc'] = 'Optioneel JSON-object dat de basissectiegewichten overschrijft specifiek tijdens de beoordeelde-quiz coach-modus (wanneer <code>quizmode=coach</code>). Nuttig voor het afdwingen van een zwaardere <code>current_page</code>-verdeling tijdens quizzen zonder de normale chat te beïnvloeden. Leeg laten om de basisgewichten over te nemen. Dezelfde validatieregels als de basisinstelling.';
$string['prompt_debug_view:title'] = 'Prompt-debuglogboekviewer';
$string['prompt_debug_view:subtitle'] = 'Per beurt samengestelde systeemprompt + per sectie uitsplitsing + gespreksgeschiedenis + huidig gebruikersbericht + bijlagemetadata, precies zoals het model ze ontving. Gebruik dit om te controleren of een sectie zoals Huidige pagina-inhoud daadwerkelijk in de prompt is terechtgekomen en om antwoordkwaliteitsproblemen op te lossen zonder te SSH\'en naar de server.';
$string['prompt_debug_view:disabled'] = 'Prompt-debugregistratie is momenteel UIT. Er worden geen nieuwe vermeldingen geschreven totdat het is ingeschakeld.';
$string['prompt_debug_view:enable_link'] = 'Open de plug-in-instellingen om "Samengestelde systeemprompt naar bestand registreren" in te schakelen.';
$string['prompt_debug_view:no_log_yet'] = 'Nog geen logbestand. Verzend minstens één chatbeurt na het inschakelen van het debuglogboek; het bestand wordt bij de eerste schrijfactie aangemaakt.';
$string['prompt_debug_view:empty'] = 'Logbestand bestaat maar is leeg. Verzend een chatbeurt en ververs.';
$string['prompt_debug_view:file_status'] = 'Grootte logbestand';
$string['prompt_debug_view:showing'] = 'Meest recente vermeldingen weergeven (nieuwste eerst), limiet';
$string['prompt_debug_view:total'] = 'Totale prompt';
$string['prompt_debug_view:budget'] = 'Budget bij vastlegging';
$string['prompt_debug_view:sections'] = 'Secties (per categorie)';
$string['prompt_debug_view:assembled_prompt'] = 'Samengestelde systeemprompt';
$string['prompt_debug_view:history'] = 'Naar het model verzonden gespreksgeschiedenis';
$string['prompt_debug_view:current_message'] = 'Huidig gebruikersbericht';
$string['prompt_debug_view:attachment'] = 'Bijlagemetadata';
$string['prompt_debug_view:show_more'] = 'Meer vermeldingen weergeven';
$string['settings:mastery_classifier_provider'] = 'Classificatie-aanbieder';
$string['settings:mastery_classifier_provider_desc'] = 'Aanbieder-ID gebruikt voor de per-beurt beheersingclassificatie. Leeg laten om de standaard AI-aanbieder over te nemen. Standaard <code>openai</code> wordt gecombineerd met het <code>gpt-4o-mini</code>-classificatiemodel hieronder — de goedkoopste TIER 1-optie voor gestructureerde uitvoerclassificatie (~$220/maand besparing bij 100k MAU t.o.v. de chattier). Indien ingesteld, levert de rij in Vergelijkingsaanbieders met dit aanbieder-ID de API-sleutel, basis-URL en temperatuur.';
$string['settings:premium_escalation_heading'] = 'Premium escalatietier (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Optionele per-beurt routering naar een premium model (standaard Claude Opus 4.8) voor prompts waarbij de werkhors chattier zichtbaar moeite heeft — doorgaans meerstaps-wiskunde, informatica en wetenschappelijk redeneren. Beslecht door de A.10 bake-off van 2026-06-09: Opus 4.8 won met 14,97/15 vs. 12,68/15 van gpt-4o op moeilijke prompts. Twee triggerpaden: regex-overeenkomst op het gebruikersbericht, OF een cursusallowlist die elke beurt escaleert. Standaard uitgeschakeld. Bij ~5% escalatie wordt ~$700/maand bovenop de basisuitgaven voor chat verwacht bij 100k [[unishort]] MAU.';
$string['settings:premium_escalation_enabled'] = 'Premium escalatieroutering inschakelen';
$string['settings:premium_escalation_enabled_desc'] = 'Wanneer ingeschakeld controleert de per-beurt router de triggerregexlijst en de cursusallowlist voor elke chatoproep; overeenkomende beurten worden naar de premium aanbieder gerouteerd. Valt terug op de werkhorstier als de premiumrij ontbreekt of niet kan worden geïnstantieerd. Beheerder-LLM-kiezer-overschrijvingen winnen altijd, zonder uitzondering.';
$string['settings:premium_escalation_provider'] = 'Premium aanbieder';
$string['settings:premium_escalation_provider_desc'] = 'Aanbieder-ID om premium oproepen via te routeren. Moet overeenkomen met een rij in Vergelijkingsaanbieders (zodat de API-sleutel, basis-URL en temperatuur van dezelfde plek komen die beheerders al beheren). Standaard <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Premium model';
$string['settings:premium_escalation_model_desc'] = 'Modelnaam doorgegeven aan de premium aanbieder. Standaard <code>claude-sonnet-5</code> conform het A.10 bake-off-oordeel.';
$string['settings:premium_escalation_triggers'] = 'Premium trigger-regexes';
$string['settings:premium_escalation_triggers_desc'] = 'Één PCRE-regex per regel (zonder scheidingstekens; hoofdletterongevoelige overeenkomst wordt automatisch toegepast). Regels die beginnen met # zijn opmerkingen. Leeg laten om de samengestelde standaardset uit de A.10 bake-off te gebruiken (meerstaps-STEM-markeringen: "derive", "prove that", "step by step", LaTeX-wiskunde, omheinde codeblokken, big-O, integralen, optimalisatie, enz.).';
$string['settings:premium_escalation_course_tags'] = 'Premium cursusallowlist';
$string['settings:premium_escalation_course_tags_desc'] = 'Één cursuskorte naam of idnummer-prefix per regel. Elke beurt in een overeenkomende cursus escaleert automatisch ongeacht de berichtregex (gebruik voor STEM-zware cursussen waar escalatie de standaard moet zijn). Overeenkomst is hoofdletterongevoelig prefix — "MATH" matcht MATH121, MATH205, enz.';
$string['settings:spend_cap_per_course_default'] = 'Standaard bestedingslimiet per cursus (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Defensieve limiet toegepast op elke cursus die geen eigen bestedingslimiet per cursus heeft geconfigureerd. Stel in op bijv. <code>30</code> om de maandelijkse uitgaven van elke cursus te begrenzen op $30 zonder individuele cursussen af te hoeven stemmen. <code>0</code> = geen standaard (alleen sitewijde en per-cursus-overschrijvinglimieten gelden). Wanneer een cursus 80% / 95% / 100% van deze limiet overschrijdt, verzendt de bestaande spend-guard meldingspijplijn de beheerdermelding (ontvangerslijst: <code>spend_notify_emails</code>, terugval op sitebeheerders). Een specifieke cursus kan altijd zijn eigen plafond verhogen door een hogere per-cursus-overschrijving in te stellen.';
$string['settings:cost_anomaly_heading'] = 'Kostanomalie-detector (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Dagelijkse geplande taak (<code>cost_anomaly_check</code>) die de sitewijde [[tutorshort]]-uitgaven van vandaag vergelijkt met de voortschrijdende mediaan van 7 dagen. Verstuurt een e-mail naar de ontvangerlijst <code>spend_notify_emails</code> (terugval op sitebeheerders) wanneer vandaag de geconfigureerde vermenigvuldiger × mediaan overschrijdt. Vangt drie storingsmodussen op die de bestaande 80% / 95% / 100%-bestedingsdrempels missen: (1) weggelopen cursus waarbij het absolute plafond niet wordt overschreden maar één cursus plotseling 10× het gebruikelijke volume genereert, (2) per ongeluk inschakelen van de premiumtier, (3) aanbieder-misrouting. Standaard uitgeschakeld; het [[tutorshort]]-interne equivalent van de Redash-query in <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'Kostanomalie-detector inschakelen';
$string['settings:cost_anomaly_enabled_desc'] = 'Wanneer ingeschakeld evalueert de dagelijkse geplande taak de uitgaven van vandaag ten opzichte van de voortschrijdende mediaan van 7 dagen en stuurt beheerders een e-mail bij een anomalie. De eerste 7 dagen na het inschakelen produceren een status <code>insufficient_history</code> (nog geen historische basislijn) en sturen nooit een melding. Per dag idempotent: een vlag in <code>config_plugins</code> voorkomt herhaalde e-mails als cron meerdere keren per dag wordt uitgevoerd.';
$string['settings:cost_anomaly_multiplier'] = 'Anomalie-vermenigvuldiger';
$string['settings:cost_anomaly_multiplier_desc'] = 'De uitgaven van vandaag moeten deze vermenigvuldiger × de mediaan van 7 dagen overschrijden om een melding te activeren. Standaard <code>2.0</code>. Verlaag naar <code>1.5</code> voor vroegere waarschuwingen (meer fout-positieven bij inschrijvingspieken). Verhoog naar <code>3.0</code> als het gebruik van [[unishort]] grillig genoeg is dat 2× pieken normaal zijn.';
$string['task:cost_anomaly_check'] = '[[tutorshort]] dagelijkse kostenanomalie-controle';

// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'Ondertekend beleidspakket (externe gedragsupdates)';
$string['settings:policy_bundle_heading_desc'] = 'Pas gedragsinstellingen (prompts, routering, escalatietriggers, RAG-afstemming, bestedingsbeleid) toe vanuit een cryptografisch ondertekend JSON-bestand zonder code-implementatie. Een dagelijkse geplande taak haalt de pakket-URL op, verifieert de Ed25519-handtekening met de onderstaande openbare sleutel en past de instellingen alleen toe als elke sleutel op de ingebouwde acceptatielijst staat en de pakketversie nieuwer is dan de laatste toegepaste. API-sleutels, URL\'s, webhooks en beveiligingsinstellingen kunnen nooit door een pakket worden ingesteld. Maak pakketten en onderteken ze met <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync).';
$string['settings:policy_bundle_enabled'] = 'Synchronisatie van beleidspakket inschakelen';
$string['settings:policy_bundle_enabled_desc'] = 'Indien ingeschakeld haalt de dagelijkse taak ondertekende pakketten op en past ze toe. Standaard uitgeschakeld. Uitschakelen stopt onmiddellijk alle synchronisaties; reeds toegepaste instellingen behouden hun waarden.';
$string['settings:policy_bundle_url'] = 'URL van beleidspakket';
$string['settings:policy_bundle_url_desc'] = 'HTTPS URL van de ondertekende pakket-JSON (bijvoorbeeld een S3-object of GitHub raw URL). De URL ondergaat dezelfde SSRF-validatie als AI-provider-eindpunten; hosts op een privénetwerk of plain-http hebben een vermelding nodig in de acceptatielijst voor vertrouwde SSRF-eindpunten.';
$string['settings:policy_bundle_pubkey'] = 'Openbare sleutel van beleidspakket';
$string['settings:policy_bundle_pubkey_desc'] = 'Base64 Ed25519 openbare sleutel die wordt gebruikt om pakkethandtekeningen te verifiëren. Genereer het sleutelpaar met <code>policy_bundle_tool.php --keygen</code>; de privésleutel blijft bij de pakketauteur en mag nooit ergens worden geüpload.';
$string['settings:policy_bundle_status'] = 'Laatste synchronisatie';
