$string['settings:active_learners_enabled'] = 'Indicator voor actieve deelnemers tonen';
$string['settings:active_learners_enabled_desc'] = 'Toont in het chatpaneel hoeveel anderen op dit moment studeren. Dit is een sociale prikkel en geen lesfunctie, en het bevraagt de server één keer per minuut voor elk geopend paneel; daarom staat het standaard uit. De indicator verschijnt alleen als er minstens twee anderen actief zijn.';

$string['task:unanswered_check'] = '[[tutorshort]] controle op onbeantwoorde vragen';
$string['settings:unanswered_check_enabled'] = 'Waarschuwen als vragen onbeantwoord blijven';
$string['settings:unanswered_check_enabled_desc'] = 'Stuurt een e-mail naar de ontvangers van uitgavenmeldingen wanneer deelnemers [[tutorshort]] vragen stellen en geen antwoord krijgen. De kostenanomaliedetectie slaat alleen aan als de uitgaven <em>stijgen</em>: een aanbieder die elke aanroep weigert kost niets en geeft geen waarschuwing. Dit bewaakt de verhouding tussen vragen en antwoorden, die naar nul zakt zodra een aanbieder uitvalt. Is de meldingslijst leeg, dan worden sitebeheerders gebruikt.';
$string['settings:unanswered_window_hours'] = 'Controlevenster (uren)';
$string['settings:unanswered_window_hours_desc'] = 'Hoe ver elke uitvoering terugkijkt. Korter reageert sneller maar heeft genoeg verkeer nodig om betekenisvol te zijn.';
$string['settings:unanswered_min_questions'] = 'Minimum aantal vragen voor een waarschuwing';
$string['settings:unanswered_min_questions_desc'] = 'Een cursus wordt pas beoordeeld vanaf dit aantal vragen in het venster. Daaronder lijken een paar deelnemers die het tabblad sluiten op een storing.';
$string['settings:unanswered_min_answer_rate'] = 'Minimale antwoordratio';
$string['settings:unanswered_min_answer_rate_desc'] = 'Waarschuw wanneer het aandeel beantwoorde vragen hieronder zakt. 0,5 vangt ook een gedeeltelijke storing. Zet op 0 om deze test uit te schakelen.';

$string['analytics:course_hidden_suffix'] = '(verborgen)';

$string['settings:hidden_categories'] = 'Verborgen cursuscategorieën';
$string['settings:hidden_categories_desc'] = 'Door komma\'s gescheiden lijst met namen of ID\'s van cursuscategorieën waarin de assistent niet mag verschijnen. Voorbeeld: "Cursusontwikkeling, 42". De assistent wordt ook automatisch verborgen wanneer de bewerkingsmodus aanstaat.';
$string['settings:provider_heading'] = 'AI-provider en gesprek';
$string['settings:provider_heading_desc'] = 'Configureer de AI-backend, het model en het gedrag tijdens gesprekken.';
$string['settings:claude_temperature_allow_prefixes'] = 'Claude-modellen die temperature accepteren';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Eén modelnaamprefix per regel. Anthropic-modellen waarvan de naam met een van deze prefixen begint, accepteren nog steeds de samplingparameter <code>temperature</code>. Bij elk Claude-model dat niet met een prefix overeenkomt, wordt temperature weggelaten (redeneermodellen vanaf Opus 4.7 weigeren de parameter met een HTTP 400). Laat leeg om de meegeleverde standaardwaarde te gebruiken.';
$string['settings:max_tokens'] = 'Maximale antwoordlengte (tokens)';
$string['settings:max_tokens_desc'] = 'Maximaal aantal tokens per AI-antwoord. Lagere waarden geven kortere, snellere antwoorden. 512 = ongeveer 2-3 zinnen, 1024 = ongeveer 1-2 alinea\'s, 2048 = langere uitleg. Stel in op 0 voor geen limiet (standaardwaarde van de provider).';
$string['settings:profile_update_interval'] = 'Interval voor bijwerken studentprofiel';
$string['settings:profile_update_interval_desc'] = 'Na dit aantal berichten van de student in een cursus maakt de assistent een leerprofiel aan (of werkt het bij) met een samenvatting van sterke punten, zwakke punten, leerstijl en interesses. Het profiel wordt in de systeemprompt opgenomen voor gepersonaliseerde antwoorden. Stel in op 0 om uit te schakelen. Standaard: 10.';
$string['settings:enable_thinking'] = 'Uitgebreid redeneren (alleen Claude)';
$string['settings:enable_thinking_desc'] = 'Schakelt adaptief redeneren in voor Claude-modellen. Claude bepaalt zelf wanneer en hoe uitgebreid het over een probleem nadenkt voordat het antwoordt. Verbetert de nauwkeurigheid bij complexe vragen, maar verhoogt het tokengebruik en de latentie. De inhoud van het redeneren wordt niet aan studenten getoond. Andere providers negeren deze instelling.';
$string['settings:rag_sources_heading'] = 'Inhoudsbronnen voor RAG';
$string['settings:rag_sources_heading_desc'] = 'Kies uit welke soorten cursusinhoud de RAG-indexeerder tekst haalt. De statusindicatoren op de <a href="{$a}">RAG-beheerpagina</a> laten zien of elke extractor beschikt over wat nodig is om te werken (bijvoorbeeld het pdftotext-programma of de Cloudflare-toelatingslijst).';
$string['settings:rag_extract_pdf'] = 'PDF-bestanden indexeren (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Haalt tekst uit geüploade PDF\'s via het programma <code>pdftotext</code> (poppler). Het pad naar het programma wordt automatisch gedetecteerd; geef het hieronder op indien nodig.';
$string['settings:rag_pdftotext_path'] = 'Pad naar het pdftotext-programma';
$string['settings:rag_pdftotext_path_desc'] = 'Laat leeg voor automatische detectie (controleert <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> en <code>which pdftotext</code>). Vul dit alleen in als uw installatie zich elders bevindt.';
$string['settings:rag_extract_docx'] = 'DOCX-bestanden indexeren (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Haalt tekst uit geüploade Word-documenten via ZipArchive van PHP. Er is geen externe afhankelijkheid nodig.';
$string['settings:rag_extract_pptx'] = 'PPTX-bestanden indexeren (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Haalt tekst uit geüploade moderne PowerPoint-presentaties via ZipArchive van PHP. Doorloopt de XML van dia\'s en sprekersnotities in diavolgorde; er is geen externe afhankelijkheid nodig. Oude binaire <code>.ppt</code>-bestanden worden niet ondersteund — sla die presentaties opnieuw op als <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'H5P-inhoud indexeren (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Doorloopt de JSON van H5P-inhoud en indexeert elk veld met tekst (vragen, antwoorden, feedback, beschrijvingen). De metadata van H5P-inhoudstypen is ruim opgezet; in randgevallen zijn enkele valse treffers te verwachten.';
$string['settings:rag_extract_scorm'] = 'SCORM-pakketten indexeren (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Pakt SCORM-pakketten uit en indexeert <code>imsmanifest.xml</code>, alle <code>.html</code>-bestanden en inhoudsteksten van Articulate Storyline. <strong>Staat standaard uit</strong>, omdat het verwerken van SCORM zwaar kan zijn. De maximale pakketgrootte wordt bepaald door <code>rag_scorm_max_mb</code>.';
$string['settings:rag_scorm_max_mb'] = 'Maximale grootte van te indexeren SCORM-pakket (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Slaat SCORM-pakketten groter dan deze waarde over om overmatig geheugengebruik te voorkomen.';
$string['settings:rag_fetch_transcripts'] = 'Transcripties ophalen voor ingesloten video\'s en interactieve onderdelen';
$string['settings:rag_fetch_transcripts_desc'] = 'Doorzoekt de inhoud van mod_page en mod_book op ingesloten iframes (Synthesia, YouTube, Articulate, Genially) en haalt de bijbehorende transcriptie-URL op bij elke insluiting (er wordt zowel boven als onder het iframe gezocht). Vereist uitgaand HTTPS-verkeer van deze server naar de host van de transcripties. <strong>Staat standaard uit</strong>; schakel het in zodra de transcriptiehost deze server op zijn toelatingslijst heeft gezet (bijvoorbeeld via een Cloudflare-IP-toegangsregel).';
$string['settings:rag_iframe_host_patterns'] = 'Patronen voor iframe-hosts';
$string['settings:rag_iframe_host_patterns_desc'] = 'Eén reguliere expressie per regel die overeenkomt met het <code>src</code>-attribuut van een iframe. Elk overeenkomend iframe wordt behandeld als een interactieve insluiting waarvan de transcriptie gekoppeld en geïndexeerd moet worden. Regels die met <code>#</code> beginnen zijn commentaar.';
$string['settings:rag_transcript_url_pattern'] = 'Patroon voor transcriptie-URL';
$string['settings:rag_transcript_url_pattern_desc'] = 'Reguliere expressie die overeenkomt met URL\'s van transcriptielinks. De indexeerder kiest de dichtstbijzijnde overeenkomende link (boven of onder) bij elk gevonden iframe en koppelt beide. Laat leeg om het koppelen van transcripties uit te schakelen.';
$string['settings:performance_heading'] = 'Prestaties';
$string['settings:performance_heading_desc'] = 'Bepaalt hoeveel cursusinhoud in de AI-prompt wordt opgenomen. Lagere waarden geven snellere antwoorden, maar minder context voor de AI.';
$string['settings:max_content_per_resource'] = 'Maximale inhoud per bron (tekens)';
$string['settings:max_content_per_resource_desc'] = 'Maximaal aantal tekens dat uit elke pagina of elk boekhoofdstuk wordt gehaald. Lagere waarden verkleinen de prompt en versnellen de antwoorden.';
$string['settings:max_total_content'] = 'Maximale totale inhoud (tekens)';
$string['settings:max_total_content_desc'] = 'Maximaal totaal aantal tekens cursusinhoud dat in de systeemprompt wordt opgenomen. Lagere waarden verkleinen de prompt en versnellen de antwoorden.';
$string['settings:spend_guard_heading'] = 'Uitgavenbewaking en optimalisatie';
$string['settings:spend_guard_heading_desc'] = 'Stel per periode uitgavenlimieten voor LLM\'s in. [[tutorshort]] pauzeert verzoeken zodra een limiet is bereikt, of wijkt uit naar een goedkopere provider uit uw failoverketen. Bekijk de <a href="{$a}">pagina Tokenkosten</a> voor de actuele uitgavenstatus en de aanbevelingen van de optimalisatie.';
$string['settings:spend_cap_period'] = 'Periode van de uitgavenlimiet';
$string['settings:spend_cap_period_desc'] = 'Hoe vaak de uitgavenlimiet opnieuw begint. Gekoppeld aan de kalender: maandelijks start op de 1e van de maand, wekelijks op maandag en dagelijks om middernacht.';
$string['settings:spend_cap_site'] = 'Sitebrede uitgavenlimiet (USD)';
$string['settings:spend_cap_site_desc'] = 'Totale limiet in USD voor alle cursussen en functies in de huidige periode. <code>0</code> = onbeperkt. De limieten per functie hieronder gaan hierboven, wanneer ze zijn ingesteld.';
$string['settings:spend_cap_chat'] = 'Chatlimiet (USD)';
$string['settings:spend_cap_chat_desc'] = 'Limiet alleen voor chat en toetsen van studenten. <code>0</code> = de sitebrede limiet gebruiken.';
$string['settings:spend_cap_voice'] = 'Spraaklimiet (USD)';
$string['settings:spend_cap_voice_desc'] = 'Limiet voor spraak (Realtime + TTS + STT). Spraak is meestal de grootste kostenpost — begrens die als eerste.';
$string['settings:spend_cap_rag'] = 'RAG-limiet (USD)';
$string['settings:spend_cap_rag_desc'] = 'Limiet voor embedding-aanroepen tijdens het indexeren van cursussen.';
$string['settings:spend_cap_analytics'] = 'Analyselimiet (USD)';
$string['settings:spend_cap_analytics_desc'] = 'Limiet voor beheerdersquery\'s van Learning Radar.';
$string['settings:spend_failover_chain'] = 'Failoverketen';
$string['settings:spend_failover_chain_desc'] = 'Wanneer een limiet is bereikt, probeert [[tutorshort]] deze providers op volgorde. Eén regel per item, met de opmaak <code>capability:label</code>. De labels verwijzen naar items bij Vergelijkingsproviders (voor <code>chat</code> / <code>analytics</code>) of Spraakproviders (voor <code>voice</code>). Regels die met <code>#</code> beginnen zijn commentaar. Voorbeeld:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Failover per aanroep (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Wanneer ingeschakeld wordt bij elke chataanroep de primaire provider omhuld met een failoverketen-decorator. Bij een time-out of 5xx-fout op een aanroep gaat [[tutorshort]] naar het volgende item in de <strong>failoverketen</strong> hierboven en opent 15 minuten lang een circuit op de falende provider. Bij elke overstap wordt een auditregel (<code>failover_fallthrough</code>) vastgelegd; controleer na inschakeling Beheer -> [[tutorshort]] -> Auditlogboek om te zien of de keten goed werkt. Staat standaard uit; schakel het pas in wanneer de keten is gevalideerd en uw instelling heeft bevestigd dat voor elke provider in de keten de vereiste verwerkersafspraken zijn geregeld.';
$string['settings:failover_timeout_chat'] = 'Failover per aanroep: time-out voor chat (seconden)';
$string['settings:failover_timeout_chat_desc'] = 'Hoe lang er op het eerste token van een chatprovider wordt gewacht voordat wordt overgestapt. Standaard 8 s. Lagere waarden stappen sneller over bij trage providers, ten koste van valse treffers bij tijdelijk trage verzoeken; hogere waarden houden de keten langer bij de primaire provider. Wordt alleen gebruikt wanneer <strong>failover per aanroep</strong> aanstaat.';
$string['settings:spend_notify_emails'] = 'Ontvangers van uitgavenwaarschuwingen';
$string['settings:spend_notify_emails_desc'] = 'Door komma\'s gescheiden e-mailadressen die bij 80%, 95% en 100% van de limiet worden gewaarschuwd. Laat leeg om alle sitebeheerders te waarschuwen.';
$string['settings:opt_cost_weight'] = 'Optimalisatie: gewicht van kosten';
$string['settings:opt_cost_weight_desc'] = 'Hoe zwaar de optimalisatie kosten laat meewegen bij het rangschikken van providers. 0.0 negeert kosten, 1.0 optimaliseert uitsluitend op kosten. Wordt samen met het gewicht van kwaliteit bekeken.';
$string['settings:opt_quality_weight'] = 'Optimalisatie: gewicht van kwaliteit';
$string['settings:opt_quality_weight_desc'] = 'Hoe zwaar de optimalisatie de tevredenheid van studenten (aandeel duimpjes omhoog) laat meewegen bij het rangschikken van providers. 0.0 negeert kwaliteit.';
$string['settings:inactivity_reminder_enabled'] = 'Herinneringen bij inactiviteit';
$string['settings:inactivity_reminder_enabled_desc'] = 'Stuurt wekelijks een e-mail naar studenten die hun cursus het ingestelde aantal dagen niet hebben bezocht.';
$string['settings:inactivity_threshold_days'] = 'Drempel voor inactiviteit (dagen)';
$string['settings:inactivity_threshold_days_desc'] = 'Aantal dagen zonder activiteit voordat er een herinneringsmail wordt verstuurd.';
$string['settings:voice_providers_heading'] = 'Spraakproviders (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Configureer een of meer spraak-API-providers. Deze instellingen staan los van de chatprovider hierboven en van de RAG-embeddingprovider — spraak heeft een eigen providerlijst omdat op dit moment alleen OpenAI en xAI eindpunten voor Realtime via WebSocket, TTS en STT aanbieden. Kies met de keuzelijsten hieronder welke geregistreerde provider elke functie verzorgt. Als er geen rijen zijn gedefinieerd, wordt de oude methode met één sleutel gebruikt (de Realtime API-sleutel hierboven of de primaire OpenAI-sleutel). Een site die Together AI / Anthropic / DeepSeek / Gemini / Mistral voor chat gebruikt, moet hier ten minste één rij instellen om spraak te laten werken.';
$string['settings:voice_active_realtime'] = 'Actieve Realtime-provider';
$string['settings:voice_active_realtime_desc'] = 'Welke geconfigureerde spraakprovider de sessies van de Realtime-spraakassistent verzorgt.';
$string['settings:voice_active_tts'] = 'Actieve TTS-provider';
$string['settings:voice_active_tts_desc'] = 'Welke geconfigureerde spraakprovider AI-antwoorden hardop voorleest.';
$string['settings:voice_active_stt'] = 'Actieve STT-provider';
$string['settings:voice_active_stt_desc'] = 'Welke provider de spraak van studenten omzet naar tekst. Laat leeg om voorrang te geven aan de zelfgehoste Whisper-server als die hieronder is ingesteld, met daarna de eerste rij spraakproviders of de oude sleutel.';
$string['settings:stt_selfhosted_enabled'] = 'Zelfgehoste transcriptie inschakelen';
$string['settings:stt_selfhosted_enabled_desc'] = 'Gebruikt de zelfgehoste Whisper-server hieronder als route voor spraak-naar-tekst bij spraakinvoer en Soapbox. Vereist hieronder een server-URL. Wanneer uitgeschakeld valt transcriptie terug op de gehoste route (OpenAI Whisper) of die in de browser, ook als er een URL is ingesteld.';
$string['settings:stt_selfhosted_warm'] = 'Voorverwarmen bij start van een Soapbox-opname';
$string['settings:stt_selfhosted_warm_desc'] = 'Wanneer ingeschakeld stuurt het starten van een Soapbox-opname een lichte "opwarm"-aanvraag (naar beste vermogen) naar de zelfgehoste transcriptieserver, zodat een host die naar nul schaalt (bijvoorbeeld Cloud Run) al opstart terwijl de student nog opneemt — zo blijft de vertraging van een koude start verborgen voor de transcriptie die bij het versturen wordt uitgevoerd. Heeft geen effect als hierboven geen URL van een zelfgehoste server is ingesteld. Staat standaard uit.';
$string['settings:voice_tab_enabled'] = 'Tabblad Spraak inschakelen';
$string['settings:voice_tab_enabled_desc'] = 'Toont het tabblad Spraak in de onderste navigatiebalk. Wanneer uitgeschakeld zien studenten alleen de tabbladen Chat en Notities. Spraakfuncties (gespreksoefening, uitspraakoefening) blijven bereikbaar via de gespreksstarters als die apart zijn ingeschakeld.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Oefenen met gesproken presentaties: hoe opnamen worden getranscribeerd en met welk beoordelingsmodel ze worden beoordeeld. Schakel Soapbox per cursus in met de Soapbox-schakelaar in het gedeelte Didactiek.';
$string['settings:soapbox_max_seconds'] = 'Maximale opnameduur Soapbox (seconden)';
$string['settings:soapbox_max_seconds_desc'] = 'Harde bovengrens voor de opnameduur van elke opdracht. Docenten mogen een kortere reeks instellen. Standaard 720 (12 minuten).';
$string['settings:soapbox_max_recordings'] = 'Maximaal aantal Soapbox-opnamen per student per opdracht';
$string['settings:soapbox_max_recordings_desc'] = 'Harde bovengrens voor het aantal opnamen dat een student voor één opdracht mag maken, ongeacht de instelling voor pogingen per opdracht. Standaard 3.';
$string['settings:soapbox_retention_days'] = 'Bewaartermijn Soapbox-opnamen (dagen)';
$string['settings:soapbox_retention_days_desc'] = 'Hoe lang een opname wordt bewaard voordat die automatisch wordt verwijderd; de transcriptie, de score en de feedback blijven behouden. Beperkt tot 1 tot 28 dagen. Korter is beter voor dataminimalisatie. Standaard 7.';
$string['settings:soapbox_video_quality'] = 'Videokwaliteit Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Resolutie en bitrate van de opname. Dit is de belangrijkste knop voor kosten en bandbreedte; een sprekend persoon in beeld is bij Standaard goed leesbaar. Laag past bij zwakke verbindingen; Hoog alleen wanneer visueel detail ertoe doet.';
$string['settings:soapbox_storage_bucket'] = 'Opslagbucket Soapbox';
$string['settings:soapbox_storage_bucket_desc'] = 'S3-bucket voor opnamen. Standaard: de gedeelde archiefbucket.';
$string['settings:soapbox_storage_region'] = 'Opslagregio Soapbox';
