$string['privacynotice:title'] = 'Privacyverklaring van [[tutorname]]';
$string['privacynotice:lastupdated'] = 'Laatst bijgewerkt: {$a}. Versie 1.0.';
$string['privacynotice:whatis'] = 'Wat [[tutorshort]] is';
$string['privacynotice:whatis_p1'] = '[[tutorshort]] is de AI-gestuurde leercoach van [[uniname]], ingebouwd in sommige cursussen. Wanneer [[tutorshort]] beschikbaar is bij een cursus, ziet u een chatwidget op de cursuspagina\'s. U kunt [[tutorshort]] vragen stellen over de lesstof, oefenvragen krijgen, uw studieplanning maken en spraakfuncties gebruiken als uw cursus die heeft ingeschakeld.';
$string['privacynotice:whatis_p2'] = '[[tutorshort]] is niet bij elke cursus van [[uniname]] beschikbaar. De beslissing om [[tutorshort]] bij een cursus in te schakelen wordt genomen door de cursusontwikkelaar.';
$string['privacynotice:collects'] = 'Welke informatie [[tutorshort]] verzamelt';
$string['privacynotice:collects_p1'] = 'Wanneer u [[tutorshort]] bij een cursus gebruikt, legt [[uniname]] uw berichten vast, de antwoorden van [[tutorshort]], de cursus en het tijdstip van elke uitwisseling, beoordelingen en feedback die u geeft, uw studieplan en herinneringsvoorkeuren als u die aanmaakt, uw gekozen avatar, en een korte profielsamenvatting die [[tutorshort]] uit uw gesprekken opstelt om toekomstige sessies te personaliseren.';
$string['privacynotice:collects_p2'] = '[[tutorshort]] verzamelt ook standaard technische gegevens die nodig zijn om de dienst te laten werken: uw Moodle-gebruikers-id, IP-adres, browsertype en een tijdstempel. [[tutorshort]] houdt zelf geen registratie bij van uw volledige naam, e-mailadres (tenzij u zich afmeldt voor e-mails, waarbij het adres wordt opgeslagen waarop de afmelding van toepassing is), huisadres, telefoonnummer (tenzij u er een opgeeft voor herinneringen), betalingsgegevens of door de overheid uitgegeven identificatienummers; waar uw naam naast [[tutorshort]]-gegevens verschijnt, is die uitgelezen uit uw bestaande [[uniname]]-account en niet door [[tutorshort]] opgeslagen.';
$string['privacynotice:uses'] = 'Hoe uw informatie wordt gebruikt';
$string['privacynotice:uses_item1'] = 'Uw vragen op dat moment beantwoorden.';
$string['privacynotice:uses_item2'] = 'De antwoorden van [[tutorshort]] op u afstemmen.';
$string['privacynotice:uses_item3'] = '[[tutorshort]] zelf verbeteren, met geanonimiseerde en geaggregeerde gegevens.';
$string['privacynotice:uses_item4'] = 'Misbruik opsporen en voorkomen.';
$string['privacynotice:uses_item5'] = 'Analysegegevens genereren waarmee cursusauteurs het cursusmateriaal kunnen verbeteren. Analysegegevens worden geanonimiseerd voordat een menselijke beoordelaar ze onder ogen krijgt.';
$string['privacynotice:uses_nosell'] = '[[uniname]] verkoopt uw informatie niet. [[uniname]] gebruikt uw gesprekken met [[tutorshort]] niet om niet-gerelateerde producten aan u te verkopen.';
$string['privacynotice:whosees'] = 'Wie uw informatie ziet';
$string['privacynotice:whosees_intro'] = 'Om uw vragen te beantwoorden werkt [[tutorshort]] achter de schermen samen met een AI-dienst (vergelijkbaar met ChatGPT of Claude). Dit is precies wat [[tutorshort]] met die dienst deelt:';
$string['privacynotice:shared_item1'] = 'Uw voornaam';
$string['privacynotice:shared_item2'] = 'Een samenvatting van het cursusmateriaal dat u studeert';
$string['privacynotice:shared_item3'] = 'De laatste 10 berichten uit uw huidige gesprek met [[tutorshort]]';
$string['privacynotice:shared_item4'] = 'Uw studieplan, als u er een hebt gemaakt';
$string['privacynotice:shared_item5'] = 'Uw profielsamenvatting, als u er een hebt gemaakt';
$string['privacynotice:whosees_never'] = 'Dit is wat [[tutorshort]] nooit deelt:';
$string['privacynotice:notshared_item1'] = 'Uw achternaam';
$string['privacynotice:notshared_item2'] = 'Uw e-mailadres';
$string['privacynotice:notshared_item3'] = 'Uw Moodle-gebruikersnaam of ID-nummer';
$string['privacynotice:notshared_item4'] = 'Uw huisadres';
$string['privacynotice:notshared_item5'] = 'Alle andere informatie waarmee u persoonlijk geïdentificeerd zou kunnen worden';
$string['privacynotice:whosees_contract'] = '[[uniname]] gebruikt alleen AI-diensten die wij zorgvuldig hebben beoordeeld en goedgekeurd. Elke dienst heeft een contract met [[uniname]] dat beperkt hoe zij uw informatie mogen gebruiken en dat hen verbiedt uw gesprekken met [[tutorshort]] te gebruiken om hun AI te trainen.';
$string['privacynotice:retention'] = 'Hoe lang [[tutorshort]] uw informatie bewaart';
$string['privacynotice:retention_item1'] = 'Uw gesprekken worden bewaard totdat u ze verwijdert of totdat de bewaartermijn voor gesprekken van de site (standaard twee jaar inactiviteit) ze automatisch verwijdert. Alleen de 10 meest recente wisselingen worden ooit naar het AI-model gestuurd.';
$string['privacynotice:retention_item2'] = 'Beoordelingen, studieplannen en herinneringen worden bewaard totdat u ze verwijdert.';
$string['privacynotice:retention_item3'] = 'Geanonimiseerde analysegegevens worden bewaard volgens het bewaarbeleid voor gegevens van [[uniname]] en kunnen niet aan u worden gekoppeld.';
$string['privacynotice:retention_item4'] = 'Audit- en operationele logboeken worden tot 365 dagen bewaard. Daarin wordt vastgelegd dat er een bericht is verzonden — het tijdstip, de cursus en het netwerkadres waarvan het kwam — maar nooit de inhoud van wat u hebt geschreven. Die vermeldingen leggen uw gebruikers-id vast, niet uw naam; waar het beeld van dat logboek voor een beheerder een naam laat zien, is die uitgelezen uit uw bestaande [[uniname]]-accountgegevens.';
$string['privacynotice:retention_deletion'] = 'Wanneer uw [[uniname]]-gebruikersaccount wordt verwijderd, worden alle [[tutorshort]]-gegevens die aan uw gebruikers-id zijn gekoppeld in dezelfde bewerking verwijderd.';
$string['privacynotice:rights'] = 'Uw rechten';
$string['privacynotice:rights_access'] = 'Inzage.';
$string['privacynotice:rights_access_desc'] = 'Bekijk uw huidige gesprek in de widget; download een volledige kopie van alle [[tutorshort]]-gegevens via de pagina met [[tutorshort]]-gebruikersinstellingen.';
$string['privacynotice:rights_download'] = 'Downloaden.';
$string['privacynotice:rights_download_desc'] = 'De pagina met gebruikersinstellingen biedt de knop "Mijn [[tutorshort]]-gegevens downloaden", die een gestructureerd bestand met al uw [[tutorshort]]-gegevens oplevert.';
$string['privacynotice:rights_delete'] = 'Verwijderen.';
$string['privacynotice:rights_delete_desc'] = 'Dezelfde pagina biedt verwijderopties op cursusniveau en globaal niveau. Verwijderen gebeurt onmiddellijk.';
$string['privacynotice:rights_correction'] = 'Correctie.';
$string['privacynotice:rights_correction_desc'] = 'Gesprekken met [[tutorshort]] zijn ruwe transcripten en worden normaal gesproken niet aangepast. Als een afgeleide vermelding onjuist lijkt, blijf [[tutorshort]] dan gebruiken of neem contact op met [[uniname]] via het onderstaande adres.';
$string['privacynotice:rights_object'] = 'Bezwaar maken of beperken.';
$string['privacynotice:rights_object_desc'] = 'U bent niet verplicht [[tutorshort]] te gebruiken. U kunt uw gegevens op elk moment verwijderen.';
$string['privacynotice:rights_portability'] = 'Overdraagbaarheid.';
$string['privacynotice:rights_portability_desc'] = 'De download heeft een standaard JSON-formaat en kan in andere systemen worden geïmporteerd.';
$string['privacynotice:rights_complaint'] = 'Klacht.';
$string['privacynotice:rights_complaint_desc'] = 'Neem contact op met [[uniname]]. Studenten in de EU, het VK, Zwitserland, Brazilië of Canada kunnen ook een klacht indienen bij hun nationale gegevensbeschermingsautoriteit.';
$string['privacynotice:international'] = 'Internationale studenten';
$string['privacynotice:international_body'] = '[[uniname]] bedient studenten wereldwijd. Als u zich in een regio met specifieke regels voor gegevensbescherming bevindt (AVG, UK GDPR, LGPD, PIPEDA, Zwitserse FADP, CCPA), dan gelden die regels voor uw [[tutorshort]]-gegevens. De rechtsgrond voor de verwerking is de uitvoering van de onderwijsovereenkomst die u met [[uniname]] hebt, in combinatie met het gerechtvaardigde belang van [[uniname]] bij het verbeteren van zijn onderwijsdiensten.';
$string['privacynotice:security'] = 'Beveiliging';
$string['privacynotice:security_intro'] = '[[tutorshort]] bevindt zich binnen het Moodle-platform van [[uniname]], dus u moet ingelogd zijn om het te gebruiken. Een paar concrete dingen die wij doen om uw informatie veilig te houden:';
$string['privacynotice:security_transit'] = 'Tijdens verzending:';
$string['privacynotice:security_transit_desc'] = 'Wanneer uw berichten tussen uw apparaat en [[tutorshort]] reizen, zijn ze versleuteld. Dat betekent dat iemand die ze zou onderscheppen alleen onleesbare code zou zien.';
$string['privacynotice:security_rest'] = 'In opslag:';
$string['privacynotice:security_rest_desc'] = 'Wanneer uw informatie wordt opgeslagen, staat die in de Moodle-database van [[uniname]], beschermd door dezelfde beveiligingsmaatregelen die [[uniname]] gebruikt voor de rest van uw studentgegevens.';
$string['privacynotice:security_incident'] = 'Als er iets misgaat:';
$string['privacynotice:security_incident_desc'] = 'Als wij ooit een veiligheidsincident vaststellen dat uw [[tutorshort]]-gegevens raakt, zal [[uniname]] u informeren zoals de wet dat vereist.';
$string['privacynotice:children'] = 'Kinderen';
$string['privacynotice:children_body'] = '[[tutorshort]] is alleen beschikbaar voor studenten die voldoen aan de leeftijdseisen van de cursus waarvoor zij zijn ingeschreven. [[uniname]] verzamelt niet bewust [[tutorshort]]-gegevens van kinderen onder de 13 jaar.';
